{
  "findings": [
    {
      "ref": "[D186]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child in Minecraft Bedrock Edition, and this can be turned off via Xbox privacy settings.",
      "stance": "risk",
      "quote": "In your child’s Xbox privacy settings, set “Others can communicate with voice, text, or invites” to Block or Friends, and turn “You can join multiplayer games” off to keep your child off public servers."
    },
    {
      "ref": "[D186]",
      "area": "money",
      "claim": "A parent reports that Minecraft pushes in-app purchases through Minecoins, and these can be blocked by requiring parental approval in Microsoft Family Safety spending settings.",
      "stance": "risk",
      "quote": "In your child’s spending settings, turn on “Ask a parent to buy things” so every Marketplace purchase (paid for with Minecoins) or Realms subscription needs your approval, or remove the saved payment method from the account entirely."
    },
    {
      "ref": "[D186]",
      "area": "data",
      "claim": "A parent reports that Minecraft collects data through Microsoft Family Safety and Xbox privacy settings, and this data can be deleted by managing the child account in Microsoft Family Safety.",
      "stance": "neutral",
      "quote": "Microsoft Family Safety sets the account rules: screen time, purchases, and which games your child can open."
    },
    {
      "ref": "[D186]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice only if the child’s account is created with a real birthdate; otherwise the protective defaults are not applied.",
      "stance": "risk",
      "quote": "If your child originally signed up with a fake adult birthdate, none of those defaults apply, and you will need to create a proper child account."
    },
    {
      "ref": "[D186]",
      "area": "content",
      "claim": "A parent reports that the game’s content is rated Everyone 10+ and contains no drinking, drugs, or sexual content, making it generally safe by content.",
      "stance": "neutral",
      "quote": "The ESRB rates Minecraft Everyone 10+ for mild fantasy violence, PEGI rates it 7, and Common Sense Media broadly agrees. There is no drinking, drugs, or sexual content, and the fighting is bloodless."
    },
    {
      "ref": "[D186]",
      "area": "developer_record",
      "claim": "A parent reports that there is no mention of fines, breaches, lawsuits, or regulatory actions against Mojang Studios or Microsoft related to Minecraft.",
      "stance": "neutral",
      "quote": "No source in the provided text mentions fines, breaches, lawsuits, or regulatory actions against the developer."
    }
  ]
}
